import sbx, json, time, re

SKIP_VARS = {
    "BASH", "BASHOPTS", "BASHPID", "BASH_ALIASES", "BASH_ARGC", "BASH_ARGV",
    "BASH_ARGV0", "BASH_CMDS", "BASH_COMMAND", "BASH_LINENO", "BASH_LOADABLES_PATH",
    "BASH_SOURCE", "BASH_SUBSHELL", "BASH_VERSINFO", "BASH_VERSION",
    "COMP_WORDBREAKS", "DIRSTACK", "EPOCHREALTIME", "EPOCHSECONDS",
    "EUID", "FUNCNAME", "GROUPS", "HISTCMD", "HOSTNAME", "HOSTTYPE",
    "LINENO", "MACHTYPE", "OLDPWD", "OPTERR", "OPTIND", "OSTYPE",
    "PPID", "PROMPT_COMMAND", "PWD", "RANDOM", "SECONDS", "SHELLOPTS",
    "SHLVL", "SRANDOM", "UID", "_"
}

def parse_shell_detail(lines):
    info = {
        "pwd": "/app", "umask": "0022", "sets": set(), "shopts": set(),
        "vars": {}, "oldpwd": None, "aliases": {}, "funcs": {}, "traps": set(), "dirs": []
    }
    i = 0
    n = len(lines)
    if i < n and lines[i].startswith("pwd "):
        info["pwd"] = lines[i][4:]
        i += 1
    if i < n and re.fullmatch(r"[0-7]{4}", lines[i]):
        info["umask"] = lines[i]
        i += 1
    while i < n:
        ln = lines[i]
        if ln.startswith(("set +o ", "set -o ")):
            info["sets"].add(ln); i += 1
        elif ln.startswith(("shopt -s ", "shopt -u ")):
            info["shopts"].add(ln); i += 1
        elif ln.startswith("declare "):
            m = re.match(r"^declare\s+\S+\s+([A-Za-z_][A-Za-z0-9_]*)(?:=(.*))?$", ln)
            if m:
                vname = m.group(1)
                if vname == "OLDPWD":
                    info["oldpwd"] = ln
                elif vname not in SKIP_VARS:
                    info["vars"][vname] = ln
            i += 1
        elif ln.startswith("alias "):
            m = re.match(r"^alias\s+([^=]+)=", ln)
            if m:
                info["aliases"][m.group(1)] = ln
            i += 1
        elif re.match(r"^[A-Za-z_][A-Za-z0-9_]*\s+\(\)\s*$", ln) and i + 1 < n and lines[i + 1].startswith("{"):
            fname = ln.split()[0]
            fbody = [ln]
            i += 1
            depth = 0
            while i < n:
                fbody.append(lines[i])
                if lines[i].strip() == "{":
                    depth += 1
                elif lines[i].strip() == "}":
                    depth -= 1
                    if depth <= 0:
                        i += 1
                        break
                i += 1
            if fname != "__sbx_state":
                info["funcs"][fname] = "\n".join(fbody)
        elif ln.startswith("trap -- "):
            info["traps"].add(ln); i += 1
        elif ln.startswith("/"):
            info["dirs"].append(ln); i += 1
        else:
            i += 1
    return info

def build_shell_restore_script(fresh_lines, target_lines):
    f = parse_shell_detail(fresh_lines)
    t = parse_shell_detail(target_lines)
    cmds = []
    if t["umask"] != f["umask"]:
        cmds.append(f"umask {t['umask']}")
    for vname in sorted(set(f["vars"]) - set(t["vars"])):
        cmds.append(f"unset {vname}")
    for vname, decl in sorted(t["vars"].items()):
        if f["vars"].get(vname) != decl:
            cmds.append(decl)
    for aname in sorted(set(f["aliases"]) - set(t["aliases"])):
        cmds.append(f"unalias {aname}")
    for aname, aln in sorted(t["aliases"].items()):
        if f["aliases"].get(aname) != aln:
            cmds.append(aln)
    for fname in sorted(set(f["funcs"]) - set(t["funcs"])):
        cmds.append(f"unset -f {fname}")
    for fname, fdef in sorted(t["funcs"].items()):
        if f["funcs"].get(fname) != fdef:
            cmds.append(fdef)
    for tr in sorted(t["traps"] - f["traps"]):
        cmds.append(tr)
    # Directory stack & PWD & OLDPWD
    dirs = t["dirs"] or [t["pwd"]]
    cmds.append("dirs -c")
    for idx, d in enumerate(reversed(dirs)):
        q = "'" + d.replace("'", "'\\''") + "'"
        if idx == 0:
            cmds.append(f"cd {q}")
        else:
            cmds.append(f"pushd {q} >/dev/null")
    if t["oldpwd"] and t["oldpwd"] != f["oldpwd"]:
        cmds.append(t["oldpwd"])
    for sh in sorted(t["shopts"] - f["shopts"]):
        cmds.append(sh)
    for st in sorted(t["sets"] - f["sets"]):
        cmds.append(st)
    return "\n".join(cmds) + "\n"

for path in [
    "/app/buffer/notes-api/shell-setup.json",
    "/app/buffer/word-count/pipeline-helpers.json",
    "/app/buffer/build-farm/env-tweaks.json",
]:
    traj = json.load(open(path))
    sb1 = sbx.create(traj["env"])
    try:
        for turn in traj["turns"]:
            sb1.keys(turn["keys"])
            time.sleep(turn["duration"])
        fp1 = sb1.fingerprint(detail=True)
        snap = sb1.snapshot()
    finally:
        sb1.terminate()
    sb2 = sbx.create(traj["env"], snapshot=snap)
    sbx.drop_snapshot(snap)
    try:
        fp2_init = sb2.fingerprint(detail=True)
        script = build_shell_restore_script(fp2_init["detail"]["shell"], fp1["detail"]["shell"])
        sb2.exec(["python3", "-c", "import sys; open('/tmp/.sbx_sh','w').write(sys.stdin.read())"], stdin=script)
        sb2.keys(" . /tmp/.sbx_sh && rm -f /tmp/.sbx_sh\n")
        time.sleep(0.25)
        fp2_after = sb2.fingerprint(detail=True)
        match = (fp2_after["fingerprint"] == fp1["fingerprint"])
        print(f"{traj['traj_id']:32s} | full fp match = {match}")
        if not match:
            s1 = set(fp1["detail"]["shell"])
            s2 = set(fp2_after["detail"]["shell"])
            print("  shell diff:", s1 ^ s2)
            print("  fp1 vs fp2:", fp1["fingerprint"], fp2_after["fingerprint"])
    finally:
        sb2.terminate()
EOF

